#define MAX_PATH_LEN 4096
#define MAX_FILENAME_LEN 256

// 允许访问的白名单目录
static const char *allowed_dirs[] = {
    "/var/data/uploads",
    "/var/data/exports"
};
#define ALLOWED_DIR_COUNT 2

// 校验文件名是否包含路径分隔符或..序列
static int is_safe_filename(const char *filename) {
    // 检查空指针或空字符串
    if (filename == NULL || filename[0] == '\0') {
        return 0;
    }
    // 检查长度
    if (strlen(filename) >= MAX_FILENAME_LEN) {
        return 0;
    }
    // 拒绝包含路径分隔符的文件名
    if (strchr(filename, '/') != NULL || strchr(filename, '\\') != NULL) {
        return 0;
    }
    // 拒绝包含".."序列（防止目录穿越）
    if (strstr(filename, "..") != NULL) {
        return 0;
    }
    return 1;
}

// 验证目标目录是否在白名单中
static int is_allowed_dir(const char *dir) {
    if (dir == NULL) {
        return 0;
    }
    for (int i = 0; i < ALLOWED_DIR_COUNT; i++) {
        if (strcmp(dir, allowed_dirs[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

// API 函数：安全地读取指定目录下的文件
int api_read_file(const char *dir, const char *filename, char *buffer, size_t buf_size) {
    char full_path[MAX_PATH_LEN];

    // 1. 目录白名单校验
    if (!is_allowed_dir(dir)) {
        return -1; // 拒绝非白名单目录
    }

    // 2. 文件名安全校验
    if (!is_safe_filename(filename)) {
        return -2; // 拒绝不安全文件名
    }

    // 3. 构造完整路径（使用snprintf防止缓冲区溢出）
    if (snprintf(full_path, sizeof(full_path), "%s/%s", dir, filename) >= sizeof(full_path)) {
        return -3; // 路径过长
    }

    // 4. 使用realpath解析并验证最终路径（防止符号链接逃逸）
    char resolved_path[MAX_PATH_LEN];
    if (realpath(full_path, resolved_path) == NULL) {
        return -4; // 文件不存在或无法解析
    }

    // 5. 再次验证解析后的路径仍位于白名单目录内
    int valid = 0;
    for (int i = 0; i < ALLOWED_DIR_COUNT; i++) {
        size_t dir_len = strlen(allowed_dirs[i]);
        if (strncmp(resolved_path, allowed_dirs[i], dir_len) == 0 &&
            (resolved_path[dir_len] == '/' || resolved_path[dir_len] == '\0')) {
            valid = 1;
            break;
        }
    }
    if (!valid) {
        return -5; // 解析后的路径不在白名单内
    }

    // 6. 安全地读取文件内容
    FILE *fp = fopen(resolved_path, "r");
    if (fp == NULL) {
        return -6;
    }

    size_t bytes_read = fread(buffer, 1, buf_size - 1, fp);
    buffer[bytes_read] = '\0';
    fclose(fp);

    return (int)bytes_read;
}

