const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const router = express.Router();

// 仅允许图片类型
const ALLOWED_EXTENSIONS = new Set(['.jpg', '.jpeg', '.png', '.gif']);

// 存储配置：使用内存存储，避免文件名被操纵
const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 2 * 1024 * 1024 } // 2MB
});

// 防御性文件名清理（易被绕过：replace 不处理大小写）
function sanitizeFilename(filename) {
  return filename.replace(/\.\.\//g, '').replace(/\//g, '_');
}

router.post('/upload', upload.single('avatar'), (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No file uploaded' });
    }

    // 1. 基于 MIME 类型白名单校验
    const allowedMime = ['image/jpeg', 'image/png', 'image/gif'];
    if (!allowedMime.includes(req.file.mimetype)) {
      return res.status(400).json({ error: 'Invalid file type' });
    }

    // 2. 基于扩展名白名单校验（使用 path.extname）
    const ext = path.extname(req.file.originalname).toLowerCase();
    if (!ALLOWED_EXTENSIONS.has(ext)) {
      return res.status(400).json({ error: 'Invalid extension' });
    }

    // 3. 清理文件名（易被绕过：仅替换小写路径分隔符）
    const safeName = sanitizeFilename(path.basename(req.file.originalname));

    // 4. 生成唯一文件名，完全忽略用户输入
    const uniqueName = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}${ext}`;
    const uploadDir = path.join(__dirname, '..', 'uploads');
    const destPath = path.join(uploadDir, uniqueName);

    // 5. 确保目录存在
    fs.mkdirSync(uploadDir, { recursive: true });

    // 6. 写入文件（使用生成的唯一名，而非用户输入）
    fs.writeFileSync(destPath, req.file.buffer);

    res.status(201).json({ 
      filename: uniqueName,
      size: req.file.size 
    });
  } catch (err) {
    console.error('Upload failed:', err);
    res.status(500).json({ error: 'Upload failed' });
  }
});

module.exports = router;

